import{_ as l,l as i,o as e,c as p,v as t,p as n,x as o,d as s,i as m,S as C}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"Calvo 与 Rotemberg","description":"","frontmatter":{"title":"Calvo 与 Rotemberg","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/calvo-rotemberg.md","filePath":"econ/calvo-rotemberg.md","lastUpdated":1789023840000}'),h={name:"econ/calvo-rotemberg.md"};function d(b,a,c,E,_,v){const r=i("Mermaid");return e(),p("div",null,[a[1]||(a[1]=t('<h1 id="calvo-与-rotemberg" tabindex="-1">Calvo 与 Rotemberg <a class="header-anchor" href="#calvo-与-rotemberg" aria-label="Permalink to &quot;Calvo 与 Rotemberg&quot;">​</a></h1><div class="epigraph"><p>新凯恩斯的粘性可以写成随机轮到改价，也可以写成对价格变动的二次惩罚；线性近似下常常走到同一条前瞻菲利普斯，微观故事并不相同。</p><footer>—— Calvo, Staggered Prices in a Utility-Maximizing Framework, JME 1983；Rotemberg, Sticky Prices in the United States, JPE 1982</footer></div><p><a href="/econ/new-keynesian">上一课</a>已经用交错调价给出前瞻菲利普斯，并声明菜单成本是替代微观、不必把 Calvo 日历当真。本课的缺口是把两种标准微观基础并列：Calvo 的外生改价概率，与 Rotemberg 的二次调价成本。NKPC 的斜率与福利含义下一课再收紧；本课只分清装置，不把三方程模型重写一遍。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>新凯恩斯课需要名义刚性，使 \\(i\\) 能暂时移动实际利率。缺口是：刚性从哪来。Calvo（1983）：每期每家厂商以固定概率 \\(1-\\theta\\) 被允许最优改价，其余厂商保持旧名义价格。Rotemberg（1982）：每期都可以改价，但 \\((p_t-p_{t-1})^2\\) 一类成本使厂商不愿大步调整。两者都能在垄断竞争下导出通胀对边际成本（从而对缺口）的前瞻关系。本课不把其中一种写成「真的价格粘性」，只说明它们如何接到上一课的 NKPC。</p><p><span class="marginnote">Calvo 的未改价厂商有错误的相对价格，加总有价格离散。Rotemberg 的厂商同质调价，没有同一时点的价格分散。福利与实证识别会分叉，线性 NKPC 却常看起来像同一条。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Calvo：能改价的厂商把未来一直不能再改的概率 \\(\\theta\\) 贴现进今天的定价，价格是未来边际成本的贴现加权。未改价份额 \\(\\theta\\) 把过去价格带进加总，通胀成为前瞻（以及，若有指数化，可含滞后）。Rotemberg：代表性垄断者每期选 \\(p_t\\)，权衡需求利润与调价成本，一阶条件给出类似 \\(\\pi_t=\\beta\\mathbb{E}_t\\pi_{t+1}+\\lambda\\cdot\\mathrm{mc}_t\\) 的式子，\\(\\lambda\\) 现在来自成本参数而不是 \\(\\theta\\)。</p>',8)),(e(),n(C,null,{default:o(()=>[m(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20NK%5B%22%E6%96%B0%E5%87%AF%E6%81%A9%E6%96%AF%E9%9C%80%E8%A6%81%E5%90%8D%E4%B9%89%E5%88%9A%E6%80%A7%22%5D%20--%3E%20CALVO%5B%22Calvo%EF%BC%9A%E9%9A%8F%E6%9C%BA%E6%94%B9%E4%BB%B7%E6%9C%BA%E4%BC%9A%22%5D%0A%20%20NK%20--%3E%20ROT%5B%22Rotemberg%EF%BC%9A%E4%BA%8C%E6%AC%A1%E8%B0%83%E4%BB%B7%E6%88%90%E6%9C%AC%22%5D%0A%20%20CALVO%20--%3E%20NKPC%5B%22%E7%BA%BF%E6%80%A7%E8%BF%91%E4%BC%BC%E4%B8%8B%E7%9A%84%E5%89%8D%E7%9E%BB%20Phillips%22%5D%0A%20%20ROT%20--%3E%20NKPC%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>菜单成本（状态依赖：偏离足够大才付一笔固定成本）是第三条。它产生的是状态依赖的调价频率，不是 Calvo 的日历概率。高通胀时 Calvo 的固定 \\(\\theta\\) 尤其不像；Rotemberg 的二次成本在大冲击下也不真实。本课承认：NK 主干用 Calvo/Rotemberg 是为了线性宏观，不是价格理论的终局。</p><h3 id="两种微观不要混用福利" tabindex="-1">两种微观不要混用福利 <a class="header-anchor" href="#两种微观不要混用福利" aria-label="Permalink to &quot;两种微观不要混用福利&quot;">​</a></h3><p>Calvo 的相对价格离散是额外扭曲：同样的通胀路径，福利损失可以大于 Rotemberg 的调价成本。把 Rotemberg 的二次项直接当社会福利函数，与 Calvo 的价格分散不是同一个对象。下一课 NKPC 若只谈斜率 \\(\\kappa\\)，可以暂时忽略这条分叉；谈最优通胀与稳定价格离散时不能忽略。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Calvo：央行提高 \\(i\\) → 需求下降 → 能改价的厂商少涨价 → 通胀减速；未改价厂商的相对价格被通胀稀释，加成波动。前瞻来自「今天改了可能锁住很多期」。Rotemberg：同样的需求下降降低想要的加价幅度，但二次成本使 \\(\\pi\\) 只动一点；没有锁定，前瞻来自平滑调价路径。灵活价格极限：\\(\\theta\\to 0\\) 或调价成本 \\(\\to 0\\)，缺口被压掉，回到上一课的中性极限。</p><p>经验上，混合 NKPC 加滞后项常拟合更好，两种纯微观都不直接给出强滞后，除非加指数化或规则拇指。那是修补，不是把 IS 的 \\(C(Y)\\) 请回。</p><p>Calvo 的 \\(\\theta\\) 把平均价格持续期写成 \\(1/(1-\\theta)\\)。这是方便参数，不是合同抽样。高通胀时调价频率应上升，固定 \\(\\theta\\) 会高估刚性——状态依赖菜单成本在这里更诚实，却较难线性化进三方程。Rotemberg 的二次成本在稳态通胀非零时要对通胀水平再处理，否则成本以 \\(\\pi^2\\) 进入，高通胀稳态的福利含义与 Calvo 的价格离散再次分叉。</p><p>上一课已经写出 \\(\\pi_t=\\beta\\mathbb{E}_t\\pi_{t+1}+\\kappa\\tilde{y}_t\\)。本课只说明 \\(\\kappa\\) 可以从 \\(\\theta\\) 来，也可以从二次成本参数来。把 \\(\\kappa\\) 写成「深结构不变」已经碰到卢卡斯批判：规则一变，连调价频率都可能变。下一课在给定微观下把 NKPC 写紧，不在本课估计 \\(\\kappa\\)。</p><p><span class="marginnote">Woodford 的利息规则装置对两种微观都适用：\\(M\\) 仍可由需求内生。本课不校准 \\(\\theta\\) 或二次成本系数。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 Calvo 概率写成合同事实，不估计菜单成本。工资粘性可以平行引入，不是否定这两种价格装置。量化栏的限价与改价是微观结构；这里的粘性是宏观名义刚性。ZLB、金融摩擦仍不在方程里。</p><p>Hall 的消费欧拉在上一课已经接到前瞻 IS；本课只给供给侧的价格装置。没有这两种微观，名义 \\(i\\) 仍可能被 \\(P\\) 的跳跃中和。有了它们，\\(\\kappa\\) 有限，缺口可以暂时存在。下一课把 \\(\\kappa\\) 与前瞻结构写成 NKPC，不在这里重做三方程。</p><p>指数化（按过去通胀自动调未改价商品）会在 Calvo 里加入滞后项，混合 NKPC 常从此来。Rotemberg 要得到滞后，通常另加习惯或规则拇指。经验拟合更好不自动等于微观更真；本课把拟合当对照，不把滞后项升格为第三种定价理论。工资 Calvo 可以平行写入，本课只钉价格侧，以免把 NKPC 提前写成工资–价格双方程。</p><p>后课默认：NK 的价格粘性默认 Calvo 或 Rotemberg 之一，线性 NKPC 可共用，福利与价格离散不可混用。下一课把这条微观收成新凯恩斯菲利普斯曲线的斜率与前瞻结构。RBC 对照是更后的课：灵活极限下这两种微观都关掉。</p><p>工资粘性可平行引入，本课不把 NKPC 提前写成工资–价格双方程。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>新凯恩斯课要刚性；本课给两种微观：随机改价与二次调价成本。</li><li>线性近似下常得同一类前瞻 Phillips；价格离散与福利不同。</li><li>菜单成本是状态依赖的第三条，不在主干默认。</li><li>灵活极限回到货币中性。</li><li>\\(\\theta\\) 或二次成本给出 \\(\\kappa\\)，不把 \\(\\kappa\\) 写成深结构不变。</li><li>出处：Calvo, JME 1983；Rotemberg, JPE 1982。</li></ul>',17))])}const P=l(h,[["render",d]]);export{B as __pageData,P as default};
